package com.smartresponse.api; import com.smartresponse.domain.*; import com.smartresponse.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.security.*; import java.util.*;
@RestController @RequestMapping("/api/v1/role-applications/{applicationId}/documents") public class DocumentController {private final RoleApplicationRepository apps;private final UserRepository users;private final VerificationDocumentRepository docs;private final Path root;public DocumentController(RoleApplicationRepository a,UserRepository u,VerificationDocumentRepository d,@Value("${app.document-storage:uploads}") String storage){apps=a;users=u;docs=d;root=Paths.get(storage).toAbsolutePath().normalize();}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<Void> upload(@PathVariable UUID applicationId,@RequestParam String documentType,@RequestPart MultipartFile file,Authentication auth)throws Exception{RoleApplication app=apps.findById(applicationId).orElseThrow();if(!app.getUser().getId().equals(users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId()))throw new SecurityException("Not your application");if(!Set.of("PHOTO","IDENTITY").contains(documentType))throw new IllegalArgumentException("Document type must be PHOTO or IDENTITY");if(file.isEmpty()||file.getSize()>5_000_000||!("application/pdf".equals(file.getContentType())||file.getContentType().startsWith("image/")))throw new IllegalArgumentException("Only PDF/image files up to 5 MB are allowed");Files.createDirectories(root.resolve(applicationId.toString()));String name=UUID.randomUUID()+"-"+file.getOriginalFilename().replaceAll("[^a-zA-Z0-9._-]","_");Path target=root.resolve(applicationId.toString()).resolve(name);Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(target)));docs.save(new VerificationDocument(app,documentType,target.toString(),hash,file.getContentType(),file.getSize()));return ResponseEntity.status(HttpStatus.CREATED).build();}}
